<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo+Black&family=Barlow+Semi+Condensed:wght@400;500;600;700&display=swap">

<style>
  .athlex-chequeo{
    --tinta:#141210;--papel:#E6DFCE;--lima:#93D920;--lima-honda:#6BA512;
    /* El rojo no estaba en la paleta: entra sólo acá, y sólo como alarma. */
    --rojo:#C2452D;--rojo-tenue:#E08C7A;--rojo-fondo:#2A1512;
    --impacto:'Archivo Black','Arial Black',Haettenschweiler,Impact,sans-serif;
    --texto:'Barlow Semi Condensed','Barlow','Segoe UI Semibold','Segoe UI',Arial,sans-serif;

    /* ── BASE = CELULAR · A SANGRE ──────────────────────────────────────────
       Mismo truco que el bloque de mensaje: `calc(50% - 50vw)` a cada lado rompe
       el margen del buy box sin adivinar el padding del tema. Margen superior 0
       y padding superior 0: lo único que separa son los 26 px con que cierra el
       bloque de arriba. Trama idéntica, para que el empalme no se vea.        */
    background:var(--tinta);color:var(--papel);font-family:var(--texto);
    margin:0 calc(50% - 50vw);max-width:100vw;
    padding:0 20px 26px;position:relative;overflow:hidden;
    background-image:radial-gradient(rgba(147,217,32,.13) 1.5px,transparent 1.6px);
    background-size:13px 13px;
  }
  .athlex-chequeo h1,.athlex-chequeo h2,.athlex-chequeo h3{color:inherit}

  /* ── LA LISTA ─────────────────────────────────────────────────────────────
     Una columna en celular: a dos, con 16 px de cuerpo, quedan renglones de
     tres palabras. El tilde es decorativo (aria-hidden): la información es que
     el ítem está en la lista, no el dibujito.                                */
  .athlex-chequeo .ax-lista{list-style:none;margin:0;padding:0;
    display:grid;grid-template-columns:1fr;gap:11px 22px}
  .athlex-chequeo .ax-lista li{display:grid;grid-template-columns:22px 1fr;
    gap:10px;align-items:start;font-size:16.5px;line-height:1.35}
  .athlex-chequeo .ax-tic{width:22px;height:22px;flex:none;margin-top:1px;
    border:2px solid var(--lima);display:grid;place-items:center}
  .athlex-chequeo .ax-tic svg{width:12px;height:12px;display:block}

  /* ── LAS DOS TARJETAS ─────────────────────────────────────────────────── */
  .athlex-chequeo .ax-duo{display:grid;grid-template-columns:1fr;gap:12px;margin:24px 0 0}
  .athlex-chequeo .ax-card{border:3px solid;padding:16px 16px 18px}
  .athlex-chequeo .ax-card p{margin:0;font-size:16.5px;line-height:1.45}
  .athlex-chequeo .ax-rot{display:inline-flex;align-items:center;gap:7px;
    font-family:var(--impacto);font-size:9.5px;letter-spacing:.15em;
    text-transform:uppercase;padding:7px 12px;margin:0 0 12px;transform:skewX(-9deg)}
  .athlex-chequeo .ax-rot span{display:inline-block;transform:skewX(9deg)}
  .athlex-chequeo .ax-rot svg{width:11px;height:11px;display:block;transform:skewX(9deg)}

  .athlex-chequeo .ax-mal{background:var(--rojo-fondo);border-color:var(--rojo)}
  .athlex-chequeo .ax-mal .ax-rot{background:var(--rojo);color:#FFF1EC}
  .athlex-chequeo .ax-mal p{color:var(--rojo-tenue)}
  .athlex-chequeo .ax-mal em{font-style:normal;font-weight:700;color:#F0705A}

  .athlex-chequeo .ax-bien{background:var(--papel);border-color:var(--lima)}
  .athlex-chequeo .ax-bien .ax-rot{background:var(--tinta);color:var(--lima)}
  .athlex-chequeo .ax-bien p{color:var(--tinta)}
  .athlex-chequeo .ax-bien em{font-style:normal;font-weight:700;color:var(--lima-honda)}

  /* 560 px: la lista pasa a dos columnas. */
  @media(min-width:560px){
    .athlex-chequeo .ax-lista{grid-template-columns:1fr 1fr}
  }

  /* ── DESKTOP ──────────────────────────────────────────────────────────────
     Vuelve a quedar contenido en la columna del buy box, igual que el bloque de
     mensaje (si no, 100vw se pasa por el ancho de la barra de scroll). Mismo
     padding lateral que él, 30 px, para que los dos alineen.                 */
  @media(min-width:900px){
    .athlex-chequeo{padding:0 30px 34px;margin:0;max-width:none}
    .athlex-chequeo .ax-lista{gap:12px 26px}
    .athlex-chequeo .ax-lista li{font-size:17px}
    .athlex-chequeo .ax-duo{gap:14px;margin-top:28px}
    .athlex-chequeo .ax-card{padding:18px 18px 20px}
    .athlex-chequeo .ax-card p{font-size:17px}
    .athlex-chequeo .ax-rot{font-size:10.5px;padding:8px 14px;margin-bottom:13px}
  }
</style>

<div class="athlex-chequeo">
  {%- assign items = ax_items | split: '|' -%}
  {%- if items.size > 0 -%}
    <ul class="ax-lista">
      {%- for it in items -%}
        {%- assign it = it | strip -%}
        {%- if it != blank -%}
          <li>
            <span class="ax-tic" aria-hidden="true">
              <svg viewBox="0 0 16 16" fill="none" stroke="#93D920" stroke-width="2.6"
                   stroke-linecap="square"><path d="M2 8.5 L6 12.5 L14 3.5"/></svg>
            </span>
            <span>{{ it }}</span>
          </li>
        {%- endif -%}
      {%- endfor -%}
    </ul>
  {%- endif -%}

  <div class="ax-duo">
    <article class="ax-card ax-mal">
      {%- if ax_mal_rot != blank -%}
        <div class="ax-rot">
          <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.6"
               stroke-linecap="square" aria-hidden="true"><path d="M3 3 L13 13 M13 3 L3 13"/></svg>
          <span>{{ ax_mal_rot }}</span>
        </div>
      {%- endif -%}
      <p>{{ ax_mal_txt }}</p>
    </article>

    <article class="ax-card ax-bien">
      {%- if ax_bien_rot != blank -%}
        <div class="ax-rot">
          <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.6"
               stroke-linecap="square" aria-hidden="true"><path d="M2 8.5 L6 12.5 L14 3.5"/></svg>
          <span>{{ ax_bien_rot }}</span>
        </div>
      {%- endif -%}
      <p>{{ ax_bien_txt }}</p>
    </article>
  </div>
</div>
